import jax.numpy as jnp
import flax.linen as nn
from jax import random
from typing import Dict, Any

def _define_hyperparameters():
    """Use the same hyperparameters as the default for a fair comparison."""
    return {
        'learning_rate': 0.001,
        'hidden_dim': 128,  # Number of CNN filters
        'dropout_rate': 0.1,
        'kernel_size': 8
    }

class CNNModel(nn.Module):
    """A simple 1D CNN for RNA sequence modeling."""
    d_output: int
    task_type: str
    hidden_dim: int
    dropout_rate: float
    kernel_size: int

    @nn.compact
    def __call__(self, x, deterministic=True):
        # x shape: (batch, seq_len, 4)
        # Conv layer expects (batch, spatial_dims..., features)
        x = nn.Conv(
            features=self.hidden_dim,
            kernel_size=(self.kernel_size,)
        )(x)
        x = nn.relu(x)
        # Global max pooling across the sequence length
        x = jnp.max(x, axis=1) # (batch, hidden_dim)

        x = nn.Dropout(rate=self.dropout_rate)(x, deterministic=deterministic)
        x = nn.Dense(self.d_output)(x)

        if self.task_type == "regression":
            return x.squeeze(-1)  # (batch,)
        else:
            return x  # (batch, d_output)

class NetworkWrapper:
    """A wrapper to provide the required init and apply methods."""
    def __init__(self, d_output, task_type, hidden_dim, dropout_rate, kernel_size):
        self.network = CNNModel(
            d_output=d_output,
            task_type=task_type,
            hidden_dim=hidden_dim,
            dropout_rate=dropout_rate,
            kernel_size=kernel_size
        )

    def init(self, rng_key, dummy_input):
        params_key, dropout_key = random.split(rng_key)
        variables = self.network.init({'params': params_key, 'dropout': dropout_key},
                                     dummy_input, deterministic=True)
        return variables['params']

    def apply(self, params, x, deterministic=True, rng_key=None):
        if deterministic:
            return self.network.apply({'params': params}, x, deterministic=True)
        else:
            if rng_key is None:
                rng_key = random.PRNGKey(0)
            return self.network.apply({'params': params}, x, deterministic=False,
                                    rngs={'dropout': rng_key})

def create_network(hparams: Dict[str, Any]):
    """Creates and returns the custom CNN network."""
    return NetworkWrapper(
        d_output=hparams["d_output"],
        task_type=hparams["task_type"],
        hidden_dim=hparams["hidden_dim"],
        dropout_rate=hparams["dropout_rate"],
        kernel_size=hparams["kernel_size"]
    )
